int main() {
    int n , m;
    cin >> n >> m;
    vector<vector<int>> grid(n, vector<int>(m, 0));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> grid[i][j];
        }
    }
    int k;
    cin >> k;
    vector<int> ans(k);
    // 统计待匹配数组中各个数字出现次数
    map<int, int> mp;
    for (int i = 0; i < k; i++) {
        cin>>ans[i];
        mp[ans[i]]++;
    }
    // 统计双指针区域中出现数字的数量
    map<int, int> total;
    int res = INT_MAX;
    // 双指针区域中已经匹配上 待匹配数字的数量
    int count  = 0;

    // 统计第一列出现的各个数字的数量  以及更新匹配上的数量
    for (int i = 0; i < n; i++) {
        int num = grid[i][0];
        total[num]++;
        if (total[num] <= mp[num]) {
            count++;
        }
    }
    // 已经完全匹配
    if (count == k) {
        cout << 1;
        return 0;
    }

    int left = 0, right = 0;
    while (right < m) {
        // 增加右边界 双指针区域并没有完全匹配上所有元素，右边界右移，增加区域
        if (count < k) {
            right++;
            if (right >= m) {
                continue;
            }
            for (int i = 0; i < n; i++) {
                int num = grid[i][right];
                total[num]++;
                if (total[num] <= mp[num]) {
                    count++;
                }
            }
            if (count == k) {
                res = min(res, right - left + 1); 
            }
        // 尝试减少左边界  已经完全匹配的情况下，尝试左边界右移缩小宽度
        } else {
            for (int i = 0; i < n; i++) {
                int num = grid[i][left];
                total[num]--;
                if (total[num] < mp[num]) {
                    count--;
                }
            }
            left++;
            if (count == k) {
                res = min(res, right - left + 1); 
            }
        }
    }

    if (res != INT_MAX) {
        cout << res;
    } else {
        cout << -1;
    }
​
    return 0;
}

