public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // 读取 n 和 m
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // 读取矩阵 grid
        int[][] grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        // 读取 k
        int k = scanner.nextInt();
        int[] ans = new int[k];
        Map<Integer, Integer> mp = new HashMap<>();

        // 统计待匹配数组中各个数字出现次数
        for (int i = 0; i < k; i++) {
            ans[i] = scanner.nextInt();
            mp.put(ans[i], mp.getOrDefault(ans[i], 0) + 1);
        }

        // 统计双指针区域中出现数字的数量
        Map<Integer, Integer> total = new HashMap<>();
        int count = 0, res = Integer.MAX_VALUE;

        // 统计第一列出现的各个数字的数量，并更新匹配上的数量
        for (int i = 0; i < n; i++) {
            int num = grid[i][0];
            total.put(num, total.getOrDefault(num, 0) + 1);
            if (total.get(num) <= mp.getOrDefault(num, 0)) {
                count++;
            }
        }

        // 已经完全匹配
        if (count == k) {
            System.out.println(1);
            return;
        }

        int left = 0, right = 0;
        while (right < m) {
            // 增加右边界，双指针区域并没有完全匹配上所有元素
            if (count < k) {
                right++;
                if (right >= m) continue;

                for (int i = 0; i < n; i++) {
                    int num = grid[i][right];
                    total.put(num, total.getOrDefault(num, 0) + 1);
                    if (total.get(num) <= mp.getOrDefault(num, 0)) {
                        count++;
                    }
                }

                if (count == k) {
                    res = Math.min(res, right - left + 1);
                }
            // 尝试减少左边界，已经完全匹配的情况下尝试缩小宽度
            } else {
                for (int i = 0; i < n; i++) {
                    int num = grid[i][left];
                    total.put(num, total.get(num) - 1);
                    if (total.get(num) < mp.getOrDefault(num, 0)) {
                        count--;
                    }
                }
                left++;
                if (count == k) {
                    res = Math.min(res, right - left + 1);
                }
            }
        }

        System.out.println(res != Integer.MAX_VALUE ? res : -1);
    }
}
