package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    reader := bufio.NewReader(os.Stdin)
​
    // 读取 n 和 m
    nm, _ := reader.ReadString('\n')
    nmSlice := splitToInt(nm)
    n, m := nmSlice[0], nmSlice[1]
​
    // 读取矩阵 grid
    grid := make([][]int, n)
    for i := 0; i < n; i++ {
        line, _ := reader.ReadString('\n')
        grid[i] = splitToInt(line)
    }
​
    // 读取 k
    kStr, _ := reader.ReadString('\n')
    k, _ := strconv.Atoi(strings.TrimSpace(kStr))
​
    // 读取 ans 数组
    ansStr, _ := reader.ReadString('\n')
    ans := splitToInt(ansStr)
​
    // 统计待匹配数组中各个数字出现次数
    mp := make(map[int]int)
    for _, num := range ans {
        mp[num]++
    }
​
    // 统计双指针区域中出现数字的数量
    total := make(map[int]int)
    count := 0
    res := int(^uint(0) >> 1) // 设置 res 为 int 最大值
​
    // 统计第一列出现的各个数字的数量，并更新匹配上的数量
    for i := 0; i < n; i++ {
        num := grid[i][0]
        total[num]++
        if total[num] <= mp[num] {
            count++
        }
    }
​
    // 已经完全匹配
    if count == k {
        fmt.Println(1)
        return
    }
​
    left, right := 0, 0
    for right < m {
        // 增加右边界，双指针区域并没有完全匹配上所有元素
        if count < k {
            right++
            if right >= m {
                continue
            }
​
            for i := 0; i < n; i++ {
                num := grid[i][right]
                total[num]++
                if total[num] <= mp[num] {
                    count++
                }
            }
​
            if count == k {
                res = min(res, right-left+1)
            }
        } else { // 尝试减少左边界，已经完全匹配的情况下尝试缩小宽度
            for i := 0; i < n; i++ {
                num := grid[i][left]
                total[num]--
                if total[num] < mp[num] {
                    count--
                }
            }
            left++
            if count == k {
                res = min(res, right-left+1)
            }
        }
    }
​
    if res != int(^uint(0)>>1) {
        fmt.Println(res)
    } else {
        fmt.Println(-1)
    }
}
