// splitToInt 将输入字符串按空格拆分并转换为整数数组
func splitToInt(s string) []int {
    fields := strings.Fields(s)
    res := make([]int, len(fields))
    for i, v := range fields {
        res[i], _ = strconv.Atoi(v)
    }
    return res
}
​
// min 返回两个整数中的最小值
func min(a, b int) int {
    if a < b {
        return a
    }
    return b
}
